  function project({ latitude, longitude }) {
    const { scale, center, translate } = PORTFOLIO_RUNTIME.journey.projection;
    return [
      translate[0] + scale * (longitude - center[0]) * radians,
      translate[1] + scale * (mercatorY(center[1]) - mercatorY(latitude)),
    ];
  }
